#import <Cocoa/Cocoa.h>
#import <Carbon/Carbon.h>

int main() {
    NSLog(@"Attempting to send Quartz events to iOS Simulator...");

    // Try to find the Simulator window
    NSArray *windows = (NSArray *)CGWindowListCopyWindowInfo(kCGWindowListOptionAll, kCGNullWindowID);

    for (NSDictionary *window in windows) {
        NSString *windowName = window[(NSString *)kCGWindowName];
        if ([windowName containsString:@"Simulator"]) {
            NSLog(@"Found Simulator window: %@", windowName);

            // Get window bounds
            CGRect windowBounds;
            CFDictionaryRef boundsDictionary = (CFDictionaryRef)window[(NSString *)kCGWindowBounds];
            CGRectMakeWithDictionaryRepresentation(boundsDictionary, &windowBounds);

            NSLog(@"Window bounds: %@", NSStringFromRect((NSRect)windowBounds));

            // Calculate the position of the Book Club room (approximately in the middle)
            CGFloat x = windowBounds.origin.x + windowBounds.size.width / 2;
            CGFloat y = windowBounds.origin.y + windowBounds.size.height / 2;

            NSLog(@"Would send long-press at approximately: %.0f, %.0f", x, y);

            // Create a mouse down event at the calculated position
            CGEventRef mouseDown = CGEventCreateMouseEvent(NULL, kCGEventLeftMouseDown, CGPointMake(x, y), 0);

            // Post the event
            CGEventPost(kCGHIDEventTap, mouseDown);
            CFRelease(mouseDown);

            // Wait 0.5 seconds (500ms)
            usleep(500000);

            // Create a mouse up event
            CGEventRef mouseUp = CGEventCreateMouseEvent(NULL, kCGEventLeftMouseUp, CGPointMake(x, y), 0);

            // Post the event
            CGEventPost(kCGHIDEventTap, mouseUp);
            CFRelease(mouseUp);

            NSLog(@"Long-press gesture sent!");
            break;
        }
    }

    CFRelease(windows);

    return 0;
}
